独立参考解答（非原书摘录）：按 HString 的 0 基 ch 数组实现，而题目位置 pos 仍采用 ADT 规定的 1 基语义：在 S 的第 pos 个字符之前插入 T，故 1<=pos<=S.length+1。分配独立的新缓冲区而非直接 realloc，可同时处理 T 与 S 别名并在分配失败时保持 S 不变。

~~~c
Status StrInsert(HString &S, int pos, HString T) {
    if (pos < 1 || pos > S.length + 1 || T.length < 0 ||
        S.length > INT_MAX - T.length) return ERROR;
    if (T.length == 0) return OK;

    int left = pos - 1;
    int n = S.length + T.length;
    char *buf = (char *)malloc((size_t)n * sizeof(char));
    if (buf == NULL) return OVERFLOW;

    for (int i = 0; i < left; ++i) buf[i] = S.ch[i];
    for (int i = 0; i < T.length; ++i) buf[left + i] = T.ch[i];
    for (int i = left; i < S.length; ++i)
        buf[T.length + i] = S.ch[i];

    if (S.ch != NULL) free(S.ch);
    S.ch = buf;
    S.length = n;
    return OK;
}
~~~

三个复制区间依次是 S 的前缀、T 和 S 的后缀，覆盖且只覆盖新串的全部位置；因而结果正是在 pos 前插入 T。pos=1、pos=S.length+1、空 S、空 T 和长度溢出均已处理。时间 O(|S|+|T|)，额外空间 O(|S|+|T|)。

独立参考解答（非原书摘录）：沿用 6.37 的普通二叉链表 BiTree 和栈的基本操作。栈元素同时保存结点指针及返回阶段：stage=0 表示左子树刚完成、尚未处理右子树；stage=1 表示右子树也已完成、现在应访问根。

~~~c
typedef struct { BiTree p; unsigned char stage; } Frame;

void PostOrder_NonRecursive(BiTree T) {
    Stack S; InitStack(&S);              // 栈元素类型为 Frame
    BiTree p = T;
    while (p != NULL || !StackEmpty(S)) {
        while (p != NULL) {
            Push(&S, (Frame){p, 0});     // 进入左子树前的返回点
            p = p->lchild;
        }
        Frame f; Pop(&S, &f);
        if (f.stage == 0) {
            f.stage = 1;
            Push(&S, f);                 // 右子树完成后才访问根
            p = f.p->rchild;
        } else {
            Visit(f.p->data);
            p = NULL;
        }
    }
}
~~~

栈中的 stage=0 帧恰表示“左子树已遍历、右子树未遍历”，stage=1 帧恰表示“两棵子树均已遍历”；因此访问顺序为左、右、根。空树不入栈。每个结点至多两次入栈、两次出栈，时间 O(n)，辅助栈空间 O(h)，其中 h 为树高。

独立参考解答（非原书摘录）：可以不设栈。对普通二叉链表增加 parent 域，并保证根的 parent 为 NULL、每条孩子边的反向 parent 正确。用 prev 记住刚离开的结点，就能判定当前是从双亲下来、从左子树回来还是从右子树回来；prev 和 cur 只是常数个工作指针，不构成栈。

~~~c
typedef struct BiPNode {
    TElemType data;
    struct BiPNode *lchild, *rchild, *parent;
} BiPNode, *BiPTree;

Status InOrder_ByParent(BiPTree root) {
    BiPTree prev = NULL, cur = root, next;
    while (cur != NULL) {
        if (prev == cur->parent) {             // 从双亲第一次到达 cur
            if (cur->lchild != NULL) next = cur->lchild;
            else {
                if (!Visit(cur->data)) return ERROR;
                next = cur->rchild ? cur->rchild : cur->parent;
            }
        } else if (prev == cur->lchild) {      // 左子树已完成
            if (!Visit(cur->data)) return ERROR;
            next = cur->rchild ? cur->rchild : cur->parent;
        } else {                                // 从右子树返回
            next = cur->parent;
        }
        prev = cur;
        cur = next;
    }
    return OK;
}
~~~

第一次到达结点时先尽量向左，左子树返回时访问结点再向右，右子树返回时向上，正是中序的左、根、右规则。空树立即返回。每条父子边只作常数次来回，时间 O(n)，额外空间 O(1)。

独立参考解答（非原书摘录）：令 k 为可修改的剩余访问次数，且输入时 k>=1。先序访问一个非空结点时先将 k 减一；恰减到 0 的结点就是所求。返回结点指针可明确区分“未找到”和结点值本身。

~~~c
BiTree PreOrderKth(BiTree T, int *k) {
    if (T == NULL || *k <= 0) return NULL;
    if (--(*k) == 0) return T;            // 先序先访问根
    BiTree q = PreOrderKth(T->lchild, k);
    if (q != NULL) return q;
    return PreOrderKth(T->rchild, k);
}

Status GetPreOrderKth(BiTree T, int k, TElemType *e) {
    if (k < 1 || e == NULL) return ERROR;
    BiTree q = PreOrderKth(T, &k);
    if (q == NULL) return ERROR;          // k 大于结点数或空树
    *e = q->data;
    return OK;
}
~~~

递归调用的顺序严格为根、左、右，每个已访问结点恰使 k 减一，因此 k 首次为 0 时正好是原先序序列第 k 个结点。找到后立即向上返回，时间 O(min(k,n))，最坏 O(n)，递归辅助空间 O(h)。

独立参考解答（非原书摘录）：空树没有叶子；非空且左右孩子都为空的结点恰为一个叶子；其余结点的叶子数是两棵子树叶子数之和。

~~~c
int LeafCount(BiTree T) {
    if (T == NULL) return 0;
    if (T->lchild == NULL && T->rchild == NULL) return 1;
    return LeafCount(T->lchild) + LeafCount(T->rchild);
}
~~~

三个分支分别对应空子树、叶结点和内部结点，递归子问题互不重叠，故归纳可得返回值正是该子树的叶子数。每个结点访问一次，时间 O(n)，递归辅助空间 O(h)。

独立参考解答（非原书摘录）：对每个非空结点先交换它的左右孩子指针，再递归处理交换后的两棵子树；交换前后对子树递归都等价，因为两棵子树都会被处理一次。

~~~c
void ExchangeLeftRight(BiTree T) {
    if (T == NULL) return;
    BiTree tmp = T->lchild;
    T->lchild = T->rchild;
    T->rchild = tmp;
    ExchangeLeftRight(T->lchild);
    ExchangeLeftRight(T->rchild);
}
~~~

空树不作操作；每个非空结点恰交换一次，故最终每个结点的左、右子树均互换且没有丢失结点。时间 O(n)，递归辅助空间 O(h)，原地修改不另建树。

独立参考解答（非原书摘录）：树高按“空树为 0、叶子为 1”计。题目未说明元素值是否唯一；以下在值重复时规定取先序遇到的第一个 x。若课程语境保证结点值唯一，该规定不影响结果；若需要指定另一个重复结点，应改为传入结点指针。

~~~c
int Height(BiTree T) {
    if (T == NULL) return 0;
    int hl = Height(T->lchild), hr = Height(T->rchild);
    return 1 + (hl > hr ? hl : hr);
}

BiTree FindFirstPre(BiTree T, TElemType x) {
    if (T == NULL) return NULL;
    if (T->data == x) return T;
    BiTree q = FindFirstPre(T->lchild, x);
    return q != NULL ? q : FindFirstPre(T->rchild, x);
}

int SubtreeDepthByValue(BiTree T, TElemType x) {
    BiTree q = FindFirstPre(T, x);
    return q == NULL ? -1 : Height(q);    // -1 表示未找到
}
~~~

FindFirstPre 找到后停止，且按根、左、右的确定顺序选择目标；Height 恰按定义返回该结点为根的子树深度。空树或 x 不存在返回 -1，避免与合法的叶子高度 1 混淆。查找和高度计算覆盖的结点总数至多为常数倍 n，时间 O(n)，递归辅助空间 O(h)。

独立参考解答（非原书摘录）：显式栈保存“源结点、对应新结点”对。新结点由 NewNode 建立并把 lchild、rchild 初始化为 NULL；每发现源结点的一条孩子边，就建立对应孩子、接到新树并把这一对压栈。

~~~c
typedef struct { BiTree from, to; } Pair;

Status CopyBiTree_NonRecursive(BiTree T, BiTree *U) {
    if (U == NULL) return ERROR;
    *U = NULL;
    if (T == NULL) return OK;

    *U = NewNode(T->data);
    if (*U == NULL) return OVERFLOW;
    Stack S; InitStack(&S);               // 元素类型为 Pair
    if (!TryPush(&S, (Pair){T, *U})) goto fail;

    while (!StackEmpty(S)) {
        Pair a; Pop(&S, &a);
        if (a.from->lchild != NULL) {
            a.to->lchild = NewNode(a.from->lchild->data);
            if (a.to->lchild == NULL ||
                !TryPush(&S, (Pair){a.from->lchild, a.to->lchild})) goto fail;
        }
        if (a.from->rchild != NULL) {
            a.to->rchild = NewNode(a.from->rchild->data);
            if (a.to->rchild == NULL ||
                !TryPush(&S, (Pair){a.from->rchild, a.to->rchild})) goto fail;
        }
    }
    DestroyStack(&S);
    return OK;

fail:
    DestroyStack(&S);
    DestroyBiTree(*U); *U = NULL;
    return OVERFLOW;
}
~~~

栈中每一对始终代表已建立数据域相同的对应结点；处理该对时按源树的左右方向补齐孩子，所以终止后新树与源树的形状和值都相同且不共享结点。空树正确复制为空树，分配或压栈失败会释放已建部分。时间 O(n)，显式栈空间 O(h)，复制出的结果树占 O(n) 空间。

独立参考解答（非原书摘录）：按层次遍历时，某轮队列中的结点数正好是该层结点数。累计层数 h，维护最大层宽 maxWidth，最后返回 maxWidth*h；空树的高度和最大层宽均取 0，繁茂度为 0。

~~~c
long long Luxuriance(BiTree T) {
    if (T == NULL) return 0;
    Queue Q; InitQueue(&Q); EnQueue(&Q, T);
    long long h = 0, maxWidth = 0;
    while (!QueueEmpty(Q)) {
        int width = QueueLength(Q);
        if (width > maxWidth) maxWidth = width;
        ++h;
        for (int i = 0; i < width; ++i) {
            BiTree p; DeQueue(&Q, &p);
            if (p->lchild != NULL) EnQueue(&Q, p->lchild);
            if (p->rchild != NULL) EnQueue(&Q, p->rchild);
        }
    }
    return maxWidth * h;
}
~~~

每轮只弹出当前层已有的 width 个结点，再把下一层入队，因而不会混层；h 是树高，maxWidth 是各层结点数的最大值。实际实现应在乘法前检查结果类型溢出。每个结点入、出队各一次，时间 O(n)；队列最大长度为最大层宽 w，额外空间 O(w)，最坏 O(n)。

独立参考解答（非原书摘录）：先求树高 H，再按左、右顺序深度优先寻找深度恰为 H-1 的第一个叶子。由于左子树在右子树之前被完整搜索，该叶子就是最左的最深叶子；path[0..H-1] 同时就是所需根到叶路径。调用者须提供容量至少为 H 的 path 数组。

~~~c
int Height(BiTree T) {
    if (T == NULL) return 0;
    int a = Height(T->lchild), b = Height(T->rchild);
    return 1 + (a > b ? a : b);
}

Boolean FindFirstLeafAtDepth(BiTree T, int dep, int target,
                             BiTree path[]) {
    if (T == NULL) return FALSE;
    path[dep] = T;
    if (T->lchild == NULL && T->rchild == NULL)
        return dep == target;
    if (FindFirstLeafAtDepth(T->lchild, dep + 1, target, path)) return TRUE;
    return FindFirstLeafAtDepth(T->rchild, dep + 1, target, path);
}

Status LeftmostDeepestPath(BiTree T, BiTree path[], int capacity, int *len) {
    if (len == NULL) return ERROR;
    int h = Height(T);
    if (h == 0) { *len = 0; return ERROR; }
    if (capacity < h) return OVERFLOW;
    if (!FindFirstLeafAtDepth(T, 0, h - 1, path)) return ERROR;
    *len = h;                              // 输出 path[0..h-1] 的 data
    return OK;
}
~~~

Height 给出的 H 是结点层数，所以目标叶的边数路径长度正是 H-1。第二趟搜索一旦找到目标即停止，path 中保留完整路径。空树无满足条件的叶子。两趟各至多访问所有结点一次，时间 O(n)，递归辅助空间 O(h)，输出路径空间 O(h)。

独立参考解答（非原书摘录）：后序计算每棵子树的结点总数。对结点 T，其左、右子树的总节点数分别为 left、right，则严格子孙数为 left+right；向双亲返回的本子树总数为 left+right+1。

~~~c
int SetDescNum(BiTree T) {
    if (T == NULL) return 0;
    int left = SetDescNum(T->lchild);
    int right = SetDescNum(T->rchild);
    T->DescNum = left + right;
    return T->DescNum + 1;
}
~~~

空子树返回 0，叶结点的 DescNum 因而为 0。归纳地，子调用返回各子树完整结点数，当前赋值排除了根本身，正好是所有严格后代数。每个结点仅访问一次，时间 O(n)，递归辅助空间 O(h)。

独立参考解答（非原书摘录）：先序中某结点的后继优先是其真实左孩子；若无左孩子则是其真实右孩子；两者都没有时才是保存的后继线索。因根指针未知，算法不能回到祖先寻找后继，所以必须把“无真实右孩子时的先序后继”直接保存在 rchild 中，并用 LTag、RTag 区分孩子指针和线索；最后一个结点的后继约定为 NULL（使用头结点时可改为头结点）。

~~~c
typedef enum { Link, Thread } PointerTag;
typedef struct PreThrNode {
    TElemType data;
    struct PreThrNode *lchild, *rchild;
    PointerTag LTag, RTag;
} PreThrNode, *PreThrTree;

PreThrTree PreSuccessor(PreThrTree p) {
    if (p == NULL) return NULL;
    if (p->LTag == Link) return p->lchild;
    if (p->RTag == Link) return p->rchild;
    return p->rchild;                    // RTag==Thread：直接后继或 NULL
}
~~~

LTag=Link 时先序定义要求先进入左子树；否则若 RTag=Link 则右孩子是下一个；再否则 p 无真实孩子，rchild 的后继线索正是答案。每种情况只检查常数个域，时间和额外空间都是 O(1)。没有标签时，非空指针无法判定它是孩子还是线索，算法不成立。

独立参考解答（非原书摘录）：后序后继线索只在没有真实右孩子时可直接放入 rchild；若 p 有真实右孩子，rchild 不能再保存外部后继，必须借助 parent 找到双亲。每个结点因此需要 parent、LTag、RTag；根可由 parent==NULL 识别，不需要另给根指针。最后一个结点的后继约定为 NULL。

~~~c
typedef enum { Link, Thread } PointerTag;
typedef struct PostThrNode {
    TElemType data;
    struct PostThrNode *lchild, *rchild, *parent;
    PointerTag LTag, RTag;
} PostThrNode, *PostThrTree;

PostThrTree FirstPost(PostThrTree q) {
    while (q->LTag == Link || q->RTag == Link) {
        if (q->LTag == Link) q = q->lchild;
        else q = q->rchild;
    }
    return q;
}

PostThrTree PostSuccessor(PostThrTree p) {
    if (p == NULL) return NULL;
    if (p->RTag == Thread) return p->rchild;

    PostThrTree q = p->parent;
    if (q == NULL) return NULL;           // p 为根，后序最后访问
    if (q->RTag == Thread || q->rchild == p) return q;
    return FirstPost(q->rchild);           // p 是有右子树双亲的左孩子
}
~~~

若 p 的 rchild 是线索，它已直接给出答案。否则 p 有真实右孩子：若 p 是双亲右孩子，或双亲没有真实右子树，后继为双亲；其余情形必须先完成双亲右子树，后继是该右子树的最左优先后序首结点 FirstPost。FirstPost 沿真实左边优先、否则真实右边下降，故正确。除最后一种外查询时间为 O(1)，最后一种最坏 O(h)，额外空间始终 O(1)。

独立参考解答（非原书摘录）：题述重连要求 x 成为 p 的左子树，若 p 原来已有真实左子树则会无处保存它；故 p 无真实左子树（p->LTag==Thread）是必要前提，下面遇到违背此前提的输入返回 ERROR。x 也必须确为“只有左子树”的独立中序全线索树，即 x->RTag==Thread。采用无头结点、首元前驱和末元后继均为 NULL 的约定；若使用头结点，只需把端点 NULL 换为头结点。

设 pred 为 p 原来的中序前驱，R 为 p 原来的真实右子树（可空），succ 为 p 原来整棵子树之后的中序后继。重连后的局部中序次序为 pred, First(x), ..., x, First(R), ..., Last(R), p, succ；当 R 为空时 x 直接在 p 前。因此只更新这四个边界线索及相应孩子链接。

~~~c
typedef enum { Link, Thread } PointerTag;
typedef struct BiThrNode {
    TElemType data;
    struct BiThrNode *lchild, *rchild;
    PointerTag LTag, RTag;
} BiThrNode, *BiThrTree;

BiThrTree FirstIn(BiThrTree q) {
    while (q->LTag == Link) q = q->lchild;
    return q;
}
BiThrTree LastIn(BiThrTree q) {
    while (q->RTag == Link) q = q->rchild;
    return q;
}

Status InsertAsLeft(BiThrTree p, BiThrTree x) {
    if (p == NULL || x == NULL ||
        p->LTag != Thread || x->RTag != Thread) return ERROR;

    BiThrTree pred = p->lchild;            // p 原来没有左孩子，故为前驱线索
    BiThrTree R = (p->RTag == Link) ? p->rchild : NULL;
    BiThrTree succ;
    if (R != NULL) succ = LastIn(R)->rchild; // LastIn(R) 的后继线索
    else succ = p->rchild;                 // p 原来的后继线索

    BiThrTree firstX = FirstIn(x);
    firstX->lchild = pred; firstX->LTag = Thread;
    if (pred != NULL && pred->RTag == Thread) pred->rchild = firstX;

    p->lchild = x; p->LTag = Link;
    if (R != NULL) {
        BiThrTree firstR = FirstIn(R);
        BiThrTree lastR = LastIn(R);
        x->rchild = R; x->RTag = Link;
        firstR->lchild = x; firstR->LTag = Thread;
        lastR->rchild = p; lastR->RTag = Thread;
    } else {
        x->rchild = p; x->RTag = Thread;
    }
    p->rchild = succ; p->RTag = Thread;
    return OK;
}
~~~

FirstIn、LastIn 均只沿 Link 下降，绝不误把线索当孩子。firstX 的前驱更新为 pred；若 pred 的右域本来就是线索，再把该线索改指 firstX。R 非空时，firstR 的前驱由原 p 改为 x、lastR 的后继改为 p；R 为空时 x 的后继直接为 p。最后 p 无右孩子，其后继恢复为 succ，故局部所有空链域仍准确指向中序前驱或后继。时间为 O(hx+hR)，即相关两棵树高度的线性量，额外空间 O(1)。

